// Create creates an upload that accepts file parts before they are assembled into a usable file. Provide the filename, purpose, byte count, and MIME type; uploads can contain up to 8 GB and expire after one hour. Add parts to the upload, then complete it to create the file.
//
// Creates an intermediate [Upload](https://developers.openai.com/api/reference/resources/uploads) object that you can add [Parts](https://developers.openai.com/api/reference/resources/uploads/subresources/parts) to. Currently, an Upload can accept at most 8 GB in total and expires after an hour after you create it. Once you complete the Upload, we will create a [File](https://developers.openai.com/api/reference/resources/files) object that contains all the parts you uploaded. This File is usable in the rest of our platform as a regular File object. For certain `purpose` values, the correct `mime_type` must be specified. Please refer to documentation for the [supported MIME types for your use case](https://developers.openai.com/api/docs/guides/tools-file-search#supported-files). For guidance on the proper filename extensions for each purpose, please follow the documentation on [creating a File](https://developers.openai.com/api/reference/resources/files/methods/create). Returns the Upload object with status `pending`.
//
// Parameters:
//
//	filename: The name of the file to upload.
//	purpose: The intended purpose of the uploaded file. See the [documentation
//	on File
//	purposes](https://developers.openai.com/api/reference/resources/files/method
//	s/create#%28resource%29%20files%20%3E%20%28method%29%20create%20%3E%20%28par
//	ams%29%200%20%3E%20%28param%29%20purpose%20%3E%20%28schema%29).
//	bytes_: The number of bytes in the file you are uploading.
//	mimeType: The MIME type of the file. This must fall within the supported
//	MIME types for your file purpose. See the supported MIME types for
//	assistants and vision.
//	expiresAfter: The expiration policy for a file. By default, files with
//	`purpose=batch` expire after 30 days and all other files are persisted until
//	they are manually deleted.
func (sdk *UploadsNamespace) Create(ctx context.Context, params CreateUploadParams, opts ...RequestOption) (*Upload, error) {
	return CreateUpload(ctx, sdk.config, params, opts...)
}

// Cancel cancels a pending upload so that no more parts can be added. Use this operation when you no longer intend to complete the upload; the returned upload object has status `cancelled`.
//
// Cancels the Upload. No Parts may be added after an Upload is cancelled. Returns the Upload object with status `cancelled`.
//
// Parameters:
//
//	uploadId: The ID of the Upload.
func (sdk *UploadsNamespace) Cancel(ctx context.Context, params CancelUploadParams, opts ...RequestOption) (*Upload, error) {
	return CancelUpload(ctx, sdk.config, params, opts...)
}

// Complete completes an upload by assembling its parts into a file that can be used on the platform. Supply the ordered part IDs and optionally an MD5 checksum; the total uploaded bytes must match the byte count specified when creating the upload. No more parts can be added after completion.
//
// Completes the [Upload](https://developers.openai.com/api/reference/resources/uploads). Within the returned Upload object, there is a nested [File](https://developers.openai.com/api/reference/resources/files) object that is ready to use in the rest of the platform. You can specify the order of the Parts by passing in an ordered list of the Part IDs. The number of bytes uploaded upon completion must match the number of bytes initially specified when creating the Upload object. No Parts may be added after an Upload is completed. Returns the Upload object with status `completed`, including an additional `file` property containing the created usable File object.
//
// Parameters:
//
//	uploadId: The ID of the Upload.
//	partIds: The ordered list of Part IDs.
//	md5: The optional md5 checksum for the file contents to verify if the bytes
//	uploaded matches what you expect.
func (sdk *UploadsNamespace) Complete(ctx context.Context, params CompleteUploadParams, opts ...RequestOption) (*Upload, error) {
	return CompleteUpload(ctx, sdk.config, params, opts...)
}

// AddPart adds a chunk of file bytes as a part of an existing upload. Send the chunk in the `data` field; each part can be at most 64 MB, and the upload can contain up to 8 GB in total. You can add parts in parallel and specify their order when you complete the upload.
//
// Adds a [Part](https://developers.openai.com/api/reference/resources/uploads/subresources/parts) to an [Upload](https://developers.openai.com/api/reference/resources/uploads) object. A Part represents a chunk of bytes from the file you are trying to upload. Each Part can be at most 64 MB, and you can add Parts until you hit the Upload maximum of 8 GB. It is possible to add multiple Parts in parallel. You can decide the intended order of the Parts when you [complete the Upload](https://developers.openai.com/api/reference/resources/uploads/methods/complete).
//
// Parameters:
//
//	uploadId: The ID of the Upload.
//	data: The chunk of bytes for this Part.
func (sdk *UploadsNamespace) AddPart(ctx context.Context, params AddUploadPartParams, opts ...RequestOption) (*UploadPart, error) {
	return AddUploadPart(ctx, sdk.config, params, opts...)
}

